contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _val1, uint _val2) public payable {
        // First SetMinSum must succeed before initialization, so no try/catch needed.
        c.SetMinSum(_val1); if (__ESBMC_reverted()) return;

        // Initialize c.
        c.Initialized(); if (__ESBMC_reverted()) return;

        // Second SetMinSum must revert after initialization and leave MinSum unchanged.
        bool reverted;
        c.SetMinSum(_val2); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Assert the general rule: after initialization, SetMinSum reverts and does not change MinSum.
        assert(reverted && c.MinSum() == _val1);
    }

    receive() external payable {}
}

